(function(t){t.JobLabContent=Object.assign(t.JobLabContent||{},{"KK-717":{scenario:{company:"Kim Son Medical Laboratory Center",supervisor:{name:"Lê Hữu Phước",role:{vi:"Trưởng khoa Xét nghiệm",en:"Head of Laboratory"}},ref_code:"QC-0611",title:{vi:"QC đạt mới trả kết quả. Tính đúng hệ số pha loãng.",en:"Pass QC before reporting. Apply the dilution factor."},brief:{vi:"Đây là tình huống đào tạo. Ca sáng tại phòng xét nghiệm, bạn rà soát phiếu duyệt kết quả QC-0611. Mẫu nội kiểm glucose mức 2 (trung bình 7,0 mmol/L, SD 0,2) cho kết quả 7,7 mmol/L. Mẫu beta-hCG của một người bệnh vượt dải tuyến tính nên được pha loãng thủ công 10 lần (1 phần mẫu + 9 phần dịch pha loãng), máy đọc 1846 mIU/mL trên mẫu đã pha. Đối chiếu phiếu nháp với hồ sơ gốc, sửa kết luận nội kiểm và kết quả hCG trả lâm sàng, rồi lập báo cáo.",en:"This is a training scenario. On the morning shift you review result approval sheet QC-0611. The level 2 glucose control (mean 7.0 mmol/L, SD 0.2) reads 7.7 mmol/L. A patient's beta-hCG sample exceeded the linear range and was manually diluted 10-fold (1 part sample + 9 parts diluent); the analyzer reads 1846 mIU/mL on the diluted sample. Compare the draft sheet with the source records, correct the QC conclusion and the hCG result to report, then write a report."},reference_title:{vi:"Biểu đồ Levey-Jennings & nhật ký pha loãng",en:"Levey-Jennings chart & dilution log"},fields:[{id:"QC_RULE",label:{vi:"Kết luận lượt chạy nội kiểm",en:"QC run conclusion"},initial:"WARNING-1-2s",expected:"REJECT-1-3s",choices:["ACCEPT","WARNING-1-2s","REJECT-1-3s"],reference:"Biểu đồ Levey-Jennings glucose",ref_value:{vi:"Glucose mức 2: trung bình 7,0 mmol/L; SD 0,2; kết quả hôm nay 7,7 mmol/L",en:"Glucose level 2: mean 7.0 mmol/L; SD 0.2; today's result 7.7 mmol/L"},hint:{vi:"Tính kết quả lệch bao nhiêu SD so với trung bình rồi áp dụng quy tắc loại bỏ của Westgard.",en:"Work out how many SDs the result is from the mean, then apply the Westgard rejection rule."}},{id:"HCG_RESULT",label:{vi:"Kết quả beta-hCG trả lâm sàng (mIU/mL)",en:"Reported beta-hCG (mIU/mL)"},initial:"1846",expected:"18460",reference:"Nhật ký pha loãng mẫu",ref_value:{vi:"Pha loãng thủ công 1 phần mẫu + 9 phần dịch pha loãng; máy đọc 1846 mIU/mL trên mẫu đã pha",en:"Manual dilution 1 part sample + 9 parts diluent; analyzer reads 1846 mIU/mL on the diluted sample"},hint:{vi:"Pha loãng thủ công thì máy không tự nhân hệ số; người duyệt phải nhân trước khi trả kết quả.",en:"With manual dilution the analyzer does not apply the factor; the reviewer must multiply before reporting."}}],sop32:{vi:"Kết quả trả = giá trị máy đọc trên mẫu đã pha x hệ số pha loãng; hệ số = (thể tích mẫu + thể tích dịch pha loãng) / thể tích mẫu. Ghi rõ hệ số trên LIS.",en:"Reported result = analyzer reading on the diluted sample x dilution factor; factor = (sample volume + diluent volume) / sample volume. Record the factor in the LIS."},context:{label:"LIS / QC-0611",metrics:[{label:{vi:"QC glucose mức 2",en:"Glucose control L2"},value:"7.7 mmol/L"},{label:{vi:"Trung bình / SD",en:"Mean / SD"},value:"7.0 / 0.2"},{label:{vi:"hCG trên mẫu pha",en:"hCG on diluted sample"},value:"1846 mIU/mL"},{label:{vi:"Mẫu cấp cứu chờ",en:"Pending ER samples"},value:"12"}]},crisis:{vi:"Khoa Cấp cứu gọi giục kết quả glucose của 12 người bệnh. Trưởng ca bảo: “Cứ duyệt trả kết quả, QC lệch chút thôi. Em sửa giá trị QC trên LIS thành 7,3 cho đạt rồi chạy lại sau.”",en:"The emergency department is chasing glucose results for 12 patients. The shift lead says: “Just approve the results, QC is only slightly off. Change the QC value in the LIS to 7.3 so it passes and rerun later.”"},options:{safe:{vi:"Không duyệt kết quả lượt chạy bị loại, không sửa dữ liệu QC, tìm nguyên nhân, hiệu chuẩn và chạy lại QC cùng mẫu bệnh nhân, dùng máy dự phòng đã đạt QC cho mẫu cấp cứu và báo Trưởng khoa.",en:"Do not release results from the rejected run or edit QC data; troubleshoot, recalibrate and rerun QC with the patient samples, use a backup analyzer that passed QC for urgent samples and inform the Head of Laboratory."},shortcut:{vi:"Sửa giá trị QC thành 7,3 trên LIS và duyệt trả 12 kết quả cho kịp cấp cứu.",en:"Change the QC value to 7.3 in the LIS and release the 12 results for the ER."},wait:{vi:"Giữ kết quả lại và chờ trưởng ca tự quyết định, không báo cho khoa Cấp cứu.",en:"Hold the results and let the shift lead decide, without telling the ER."}},questions:{vi:["Vì sao lượt chạy phải kết luận REJECT-1-3s và kết quả hCG đúng là 18460 mIU/mL? Trình bày từ dữ liệu gốc.","Bạn bảo đảm kết quả cấp cứu kịp thời mà vẫn tuân thủ ISO 15189 và quy trình nội kiểm thế nào?"],en:["Why must the run be REJECT-1-3s and why is the correct hCG 18460 mIU/mL? Show it from the source data.","How do you deliver urgent results on time while still complying with ISO 15189 and the QC procedure?"]},hints:{vi:["Tính độ lệch chuẩn hóa (kết quả - trung bình) / SD và so với ngưỡng 2SD, 3SD.","Xác định hệ số pha loãng từ thể tích mẫu và dịch pha loãng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không trả kết quả khi QC bị loại và tuyệt đối không sửa dữ liệu QC."],en:["Compute the z-score (result - mean) / SD and compare it with the 2SD and 3SD limits.","Derive the dilution factor from the sample and diluent volumes in SOP 3.2.","Re-read SOP 4.2: never report results from a rejected QC run and never edit QC data."]}},learning:{summary:{vi:"Kỹ thuật viên xét nghiệm y học thực hiện các xét nghiệm huyết học, sinh hóa, miễn dịch, vi sinh để hỗ trợ chẩn đoán và theo dõi điều trị. Người làm nghề kiểm soát chất lượng ở cả ba giai đoạn trước, trong và sau xét nghiệm, vận hành và bảo trì thiết bị, thực hiện nội kiểm, ngoại kiểm và an toàn sinh học. Kết quả chính xác, kịp thời và trung thực là giá trị cốt lõi của nghề.",en:"A medical laboratory technologist performs haematology, chemistry, immunology and microbiology tests that support diagnosis and treatment monitoring. The role controls quality across the pre-analytical, analytical and post-analytical phases, runs and maintains analyzers, performs internal and external QC and follows biosafety. Accurate, timely and honest results are the core value of the profession."},responsibilities:{vi:["Tiếp nhận, kiểm tra và từ chối mẫu không đạt theo tiêu chí của phòng xét nghiệm.","Chạy nội kiểm, đánh giá theo quy tắc Westgard trước khi chạy mẫu người bệnh.","Vận hành, hiệu chuẩn, bảo trì thiết bị và ghi nhật ký đầy đủ.","Duyệt kết quả, xử lý mẫu vượt dải đo, báo giá trị nguy hiểm cho lâm sàng.","Tham gia ngoại kiểm, tuân thủ an toàn sinh học và quản lý chất thải y tế."],en:["Receive and check samples and reject unsuitable ones per laboratory criteria.","Run internal QC and evaluate it with Westgard rules before patient samples.","Operate, calibrate and maintain analyzers and keep complete logs.","Validate results, handle out-of-range samples and phone critical values to clinicians.","Join external quality assessment, follow biosafety and manage medical waste."]},competencies:[{name:{vi:"Kiểm soát chất lượng",en:"Quality control"},desc:{vi:"Đọc biểu đồ Levey-Jennings, áp dụng đa quy tắc Westgard và hành động khắc phục đúng.",en:"Read Levey-Jennings charts, apply Westgard multirules and take the right corrective action."}},{name:{vi:"Kỹ thuật xét nghiệm",en:"Analytical technique"},desc:{vi:"Thực hiện chuẩn xác pha loãng, ly tâm, pipet và quy trình vận hành chuẩn của từng xét nghiệm.",en:"Perform dilutions, centrifugation, pipetting and each test's SOP precisely."}},{name:{vi:"Nhận định kết quả",en:"Result interpretation"},desc:{vi:"Phát hiện kết quả bất thường, nhiễu do tan máu, mỡ máu và mâu thuẫn với lâm sàng.",en:"Spot abnormal results, haemolysis or lipaemia interference and clinical inconsistencies."}},{name:{vi:"An toàn sinh học",en:"Biosafety"},desc:{vi:"Dùng tủ an toàn sinh học, phương tiện bảo hộ và xử lý sự cố đổ tràn đúng quy trình.",en:"Use biosafety cabinets and protective equipment and handle spills correctly."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Không sửa dữ liệu QC hay kết quả; mọi chỉnh sửa trên LIS phải có lý do và lưu vết.",en:"Never alter QC data or results; every LIS correction needs a reason and an audit trail."}}],knowledge:{vi:["ISO 15189:2022 về yêu cầu chất lượng và năng lực của phòng xét nghiệm y tế.","Quyết định 2429/QĐ-BYT năm 2017 về tiêu chí đánh giá mức chất lượng phòng xét nghiệm y học.","Nghị định 103/2016/NĐ-CP về bảo đảm an toàn sinh học tại phòng xét nghiệm.","Đa quy tắc Westgard (1-2s, 1-3s, 2-2s, R-4s, 4-1s, 10x) và biểu đồ Levey-Jennings.","Ngoại kiểm, thử nghiệm thành thạo và đánh giá độ lệch, độ chụm của phương pháp.","Sai số giai đoạn trước xét nghiệm: tan máu, sai ống chống đông, bảo quản mẫu."],en:["ISO 15189:2022 on quality and competence requirements for medical laboratories.","Decision 2429/QD-BYT (2017) on quality level criteria for medical laboratories.","Decree 103/2016/ND-CP on laboratory biosafety.","Westgard multirules (1-2s, 1-3s, 2-2s, R-4s, 4-1s, 10x) and Levey-Jennings charts.","External quality assessment, proficiency testing and method bias and precision.","Pre-analytical errors: haemolysis, wrong anticoagulant tube and sample storage."]},tools:["Máy xét nghiệm sinh hóa, miễn dịch tự động","Hệ thống thông tin xét nghiệm (LIS)","Phần mềm nội kiểm Levey-Jennings","Tủ an toàn sinh học cấp II","Pipet và máy ly tâm đã hiệu chuẩn"],kpis:{vi:["Thời gian trả kết quả (TAT) cho mẫu cấp cứu và mẫu thường.","Tỷ lệ mẫu bị từ chối do lỗi trước xét nghiệm.","Kết quả ngoại kiểm đạt yêu cầu theo từng chương trình.","Số kết quả trả khi QC chưa đạt (mục tiêu bằng 0)."],en:["Turnaround time (TAT) for urgent and routine samples.","Share of samples rejected for pre-analytical errors.","Acceptable EQA results per programme.","Results released while QC had failed (target zero)."]},day:[{time:"06:30",vi:"Khởi động máy, bảo trì hằng ngày và chạy nội kiểm hai mức.",en:"Start up analyzers, do daily maintenance and run two-level QC."},{time:"07:30",vi:"Đánh giá QC theo Westgard, chỉ chạy mẫu người bệnh khi QC đạt.",en:"Evaluate QC by Westgard rules and run patient samples only after a pass."},{time:"09:00",vi:"Tiếp nhận mẫu, kiểm tra tan máu, đông dây và từ chối mẫu không đạt.",en:"Receive samples, check for haemolysis or clots and reject unsuitable ones."},{time:"11:00",vi:"Duyệt kết quả, pha loãng mẫu vượt dải đo và báo giá trị nguy hiểm.",en:"Validate results, dilute out-of-range samples and phone critical values."},{time:"14:00",vi:"Thực hiện ngoại kiểm, ghi nhật ký thiết bị và xử lý chất thải.",en:"Run EQA samples, update instrument logs and handle waste."}],mistakes:{vi:["Coi kết quả QC vượt 3SD là cảnh báo và vẫn trả kết quả người bệnh.","Quên nhân hệ số khi pha loãng mẫu thủ công.","Sửa giá trị QC trên LIS cho đạt để kịp trả kết quả."],en:["Treating a QC result beyond 3SD as a warning and still reporting patients.","Forgetting the factor after a manual dilution.","Editing QC values in the LIS to pass and report faster."]},career:[{vi:"Kỹ thuật viên xét nghiệm",en:"Medical laboratory technician"},{vi:"Kỹ thuật viên chính / Phụ trách chuyên môn một mảng",en:"Senior technologist / Section lead"},{vi:"Quản lý chất lượng phòng xét nghiệm",en:"Laboratory quality manager"},{vi:"Trưởng khoa hoặc Giám đốc trung tâm xét nghiệm",en:"Head of laboratory / Laboratory director"}],glossary:[{term:"IQC",vi:"Nội kiểm tra chất lượng: chạy mẫu kiểm tra đã biết giá trị để giám sát độ chính xác mỗi lượt chạy.",en:"Internal quality control: running known control samples to monitor each run's accuracy."},{term:"EQA",vi:"Ngoại kiểm: so sánh kết quả với các phòng xét nghiệm khác qua mẫu của đơn vị tổ chức độc lập.",en:"External quality assessment comparing results with other labs using an independent provider's samples."},{term:"Westgard 1-3s",vi:"Quy tắc loại bỏ khi một kết quả QC vượt trung bình cộng hoặc trừ 3 độ lệch chuẩn.",en:"Rejection rule triggered when one QC result exceeds the mean plus or minus 3 SD."},{term:"TAT",vi:"Thời gian từ khi nhận mẫu đến khi trả kết quả cho lâm sàng.",en:"Turnaround time from sample receipt to result release."},{term:"Dải tuyến tính",vi:"Khoảng nồng độ máy đo chính xác; vượt dải phải pha loãng và nhân hệ số.",en:"Concentration range measured accurately; above it, dilute and apply the factor."}],quiz:[{q:{vi:"Mẫu pha loãng thủ công 1 phần mẫu + 4 phần dịch, máy đọc 320. Kết quả trả là bao nhiêu?",en:"A sample is manually diluted 1 part + 4 parts diluent and reads 320. What do you report?"},options:{vi:["64","320","1600","1280"],en:["64","320","1600","1280"]},answer:2,explain:{vi:"Hệ số = (1 + 4) / 1 = 5; kết quả = 320 x 5 = 1600.",en:"Factor = (1 + 4) / 1 = 5; result = 320 x 5 = 1600."}},{q:{vi:"Hai lượt chạy liên tiếp của cùng một mức QC đều vượt +2SD. Vi phạm quy tắc nào?",en:"Two consecutive runs of the same QC level both exceed +2SD. Which rule is violated?"},options:{vi:["1-2s","2-2s","R-4s","10x"],en:["1-2s","2-2s","R-4s","10x"]},answer:1,explain:{vi:"2-2s: hai kết quả liên tiếp cùng phía vượt 2SD, gợi ý sai số hệ thống, phải loại lượt chạy.",en:"2-2s: two consecutive results beyond 2SD on the same side, suggesting systematic error; reject the run."}},{q:{vi:"Trưởng ca yêu cầu sửa giá trị QC trên LIS cho đạt để trả kết quả cấp cứu. Bạn làm gì?",en:"The shift lead asks you to edit a QC value in the LIS so urgent results can go out. What do you do?"},options:{vi:["Từ chối, khắc phục, chạy lại QC và dùng máy dự phòng đã đạt QC","Sửa vì là mẫu cấp cứu","Trả kết quả kèm ghi chú miệng","Xóa lượt QC lỗi khỏi hệ thống"],en:["Refuse, troubleshoot, rerun QC and use a backup analyzer that passed QC","Edit it because the samples are urgent","Report with a verbal caveat","Delete the failed QC run"]},answer:0,explain:{vi:"Sửa dữ liệu QC là gian lận và có thể gây chẩn đoán sai; cấp cứu được đáp ứng bằng phương án hợp lệ.",en:"Editing QC data is fraud and can cause misdiagnosis; urgency is met by valid alternatives."}},{q:{vi:"Mẫu xét nghiệm kali bị tan máu rõ. Cách xử lý đúng là gì?",en:"A potassium sample is clearly haemolysed. What is the correct action?"},options:{vi:["Trả kết quả bình thường","Trừ bớt 1 mmol/L rồi trả","Chạy lại trên cùng mẫu","Ghi nhận, báo lâm sàng và yêu cầu lấy lại mẫu"],en:["Report it as usual","Subtract 1 mmol/L and report","Rerun the same sample","Record it, inform the ward and request a new sample"]},answer:3,explain:{vi:"Tan máu giải phóng kali từ hồng cầu làm tăng giả kết quả; phải lấy lại mẫu.",en:"Haemolysis releases potassium from red cells and falsely raises it; a new sample is needed."}}],tools_en:["Automated chemistry & immunoassay analyzer","Laboratory information system (LIS)","Levey-Jennings internal QC software","Class II biosafety cabinet","Calibrated pipettes and centrifuges"]}}})})(window.KKR);
